using LUMAR_ERP_API_V2.DTOs.Suppliers; using LUMAR_ERP_API_V2.Services; using Microsoft.AspNetCore.Mvc; namespace LUMAR_ERP_API_V2.Controllers;
[ApiController][Route("suppliers")]public sealed class SuppliersController(ISupplierService s):ControllerBase { [HttpGet]public async Task<ActionResult<IReadOnlyList<SupplierListDto>>> All(CancellationToken c)=>Ok(await s.GetAllAsync(c)); [HttpGet("{id:int}")]public async Task<ActionResult<SupplierDetailsDto>> One(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(x.Value!);}[HttpGet("{id:int}/transactions")]public async Task<ActionResult<IReadOnlyList<SupplierTransactionDto>>> Transactions(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetTransactionsAsync(id,c));}[HttpGet("{id:int}/ledger")]public async Task<ActionResult<IReadOnlyList<SupplierLedgerEntryDto>>> Ledger(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetLedgerAsync(id,c));}[HttpGet("{id:int}/invoices")]public async Task<ActionResult<IReadOnlyList<SupplierInvoiceDto>>> Invoices(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetInvoicesAsync(id,c));}[HttpGet("{id:int}/payments")]public async Task<ActionResult<IReadOnlyList<SupplierPaymentDto>>> Payments(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetPaymentsAsync(id,c));}[HttpGet("{id:int}/payment-allocations")]public async Task<ActionResult<IReadOnlyList<SupplierPaymentAllocationDto>>> Allocations(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetAllocationsAsync(id,c));}[HttpPost][HttpPut("{id:int}")][HttpDelete("{id:int}")]public IActionResult Disabled()=>StatusCode(405,"Supplier writes are disabled while LUMAR_ERP is read-only.");private async Task<(SupplierDetailsDto? Value,ActionResult? Error)> Parent(int id,CancellationToken c){if(id<=0)return(null,BadRequest("Supplier id must be positive."));var x=await s.GetByIdAsync(id,c);return x is null?(null,NotFound()):(x,null);}}